/*
 * A195697  First denominator and then numerator in a fraction expansion of
 *          log(2) - Pi/8.
 * https://oeis.org/A195697
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  frac, sign
 * Formula:   not stated
 * Range:     i8 n <= 16, i16 n <= 53, i32 n <= 53, i64 n <= 53, i128 n <= 53,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * Sequence A195697:  First denominator and then numerator in a fraction expansion
 * of log(2) – π/8.
 *
 * The terms are generated by iterating over the odd integers s = 1, 3, 5, … .
 * For each s we produce:
 *   - d₁ = s · (s + 1)          (always present)
 *   - the numerator +1
 *   - if s ≡ 1 (mod 4) we also produce
 *         d₂ = s · (s + 2)
 *         the numerator –1
 *
 * The sequence is therefore the concatenation of the pairs
 *   d₁, +1, [d₂, –1] (where the bracketed part appears only when s ≡ 1 mod 4),
 * in increasing order of the odd integers s.
 *
 * Examples:
 *   s = 1:  2,  1,  3,  -1
 *   s = 3:  12,  1
 *   s = 5:  30,  1,  35,  -1
 *   ...
 *
 * This directly yields the OEIS terms:
 *   2, 1, 3, -1, 12, 1, 30, 1, 35, -1, 56, 1, 90, 1, 99, -1, 132, 1, 182, 1, 195, -1, 240, 1, …
 */

seq_t a(idx_t n)
{
    /* n is 1‑based.  pos tracks the current output position. */
    idx_t pos = 1;
    for (idx_t s = 1; ; s += 2) {
        /* First denominator d₁ = s·(s+1).  n odd indices. */
        seq_t d1 = (seq_t)s * ((seq_t)s + 1);
        if (pos == n) return d1;
        pos++;

        /* Then its numerator +1. */
        if (pos == n) return (seq_t)1;
        pos++;

        /* If s ≡ 1 (mod 4) we have a second denominator d₂ = s·(s+2). */
        if (s % 4 == 1) {
            seq_t d2 = (seq_t)s * ((seq_t)s + 2);
            if (pos == n) return d2;
            pos++;

            /* Its numerator is –1. */
            if (pos == n) return (seq_t)-1;
            pos++;
        }
    }
}
